INSERT IGNORE INTO `base_translation` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3003, 'ko-KR', '<h2>개인정보 보호정책</h2><p>애플리케이션을 이용해 주셔서 감사합니다. 개인정보를 소중히 보호하며 계정 로그인, 애플리케이션 기능과 고객 지원에 필요한 범위에서만 처리합니다.</p><h3>1. 정보 이용</h3><p>관련 법령과 본 정책에 따라 정보를 이용하며 관련 없는 목적으로 사용하지 않습니다.</p><h3>2. 이용자의 권리</h3><p>법률에 따라 개인정보를 조회, 정정 또는 삭제하거나 애플리케이션에 공개된 채널로 문의할 수 있습니다.</p>');
INSERT IGNORE INTO `base_translation` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3004, 'ko-KR', '<h2>서비스 약관</h2><p>애플리케이션에 오신 것을 환영합니다. 사용하기 전에 본 약관과 관련 규칙을 읽고 이해해 주세요. 애플리케이션 서비스를 이용하면 본 약관에 동의한 것으로 봅니다.</p><h3>1. 서비스 이용</h3><p>각 기능을 법령과 페이지 안내에 따라 적법하게 이용해야 하며, 불법 행위나 타인의 권리를 침해하는 활동에 사용할 수 없습니다.</p><h3>2. 약관 변경</h3><p>사업 및 법령의 변경에 따라 약관을 업데이트하고 변경된 내용을 애플리케이션에 표시합니다.</p>');
